import pytest
from operations import Calculator

@pytest.fixture
def calc():
    return Calculator()

def test_add(calc):
    assert calc.add(10, 5) == 15
    assert calc.add(-1, 1) == 0

def test_subtract(calc):
    assert calc.subtract(10, 5) == 5
    assert calc.subtract(5, 10) == -5

def test_multiply(calc):
    assert calc.multiply(10, 5) == 50
    assert calc.multiply(0, 5) == 0

def test_divide(calc):
    assert calc.divide(10, 2) == 5
    assert calc.divide(5, 2) == 2.5

def test_divide_zero(calc):
    with pytest.raises(ValueError):
        calc.divide(10, 0)

def test_history_copy(calc):
    calc.add(1, 1)
    history = calc.get_history()
    history.append(("fake", 0, 0, 0))
    assert len(calc.get_history()) == 1

def test_clear_history(calc):
    calc.add(1, 1)
    calc.clear_history()
    assert len(calc.get_history()) == 0

def test_history_integrity(calc):
    calc.add(2, 3)
    calc.multiply(4, 5)
    history = calc.get_history()
    assert history[0] == ("add", 2.0, 3.0, 5.0)
    assert history[1] == ("multiply", 4.0, 5.0, 20.0)

